validator:
function validate(input) {
  const [{ Scores = [] }] = input;
  const ids = new Set();
  for (const [id, name, ...marks] of Scores) {
    if (id === null) return 'Every student needs a student_id.';
    if (ids.has(id)) return `student_id ${id} appears twice.`;
    ids.add(id);
    if (name === null) return `Student ${id} needs a name.`;
    if (marks.some(m => !Number.isInteger(m))) return `Student ${id} needs an integer score on every assignment.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const names = ['Owen', 'Claire', 'Julian', 'Peyton', 'David', 'Camila', 'Mia', 'Noah'];
  // Small cases use a few marks so totals tie and the extremes come from different assignments.
  const marks = [0, 37, 50, 64, 100];
  const mark = () => small ? marks[Math.floor(rand() * marks.length)] : Math.floor(rand() * 101);
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Scores = [];
  for (let i = 0; i < count; i++) Scores.push([small ? 300 + i * 11 : i + 1, names[Math.floor(rand() * names.length)], mark(), mark(), mark()]);
  return [{ Scores }];
}
